on conflict(country,source,observed_on) do update set raw_value=excluded.raw_value,raw_rank=excluded.raw_rank,reliability=excluded.reliability,source_url=excluded.source_url,updated_at=now();

values('New Zealand','OFC','iffhs_world_rank_2025_rank_only',107,107,'2025-12-31',0.65,'https://iffhs.com/yo/news/iffhs-continental-ranking-ofc-leagues-2021-2025-4950','IFFHS states New Zealand Premiership was 107th in the 2025 world ranking and first in OFC.')
